# catch_at_length ----
## Setup ----
# A 3-year, 4-length-bin (25, 30, 35, 40 mm) catch-at-length model with 1
# directed pot fishery (retained + discarded catch and length comps), 1 survey
# (mature index and immature/mature length comps), and 2 growth-increment
# observations.
cal_years <- 2001:2003
cal_lengths <- c(25, 30, 35, 40)
cal_weights <- c(0.0001, 0.0002, 0.0004, 0.0008)
cal_terminal_molt <- c(0.1, 0.3, 0.7, 0.95)

cal_data <- dplyr::bind_rows(
  # Directed fishery retained catch
  data.frame(
    type = "catch_retained",
    fleet = "pot_fleet",
    age = NA_real_,
    length = NA_real_,
    maturity = NA_character_,
    timing = cal_years,
    observed = c(10, 12, 11),
    unit = "mt",
    uncertainty = "~ dlnorm(meanlog = log_catch_retained_expected, sdlog = 0.05)"
  ),
  # Directed fishery discarded catch
  data.frame(
    type = "catch_discarded",
    fleet = "pot_fleet",
    age = NA_real_,
    length = NA_real_,
    maturity = NA_character_,
    timing = cal_years,
    observed = c(3, 4, 3.5),
    unit = "mt",
    uncertainty = "~ dlnorm(meanlog = log_catch_discarded_expected, sdlog = 0.07)"
  ),
  # Directed fishery retained length comps
  data.frame(
    type = "length_comp",
    fleet = "pot_fleet",
    age = NA_real_,
    length = rep(cal_lengths, times = length(cal_years)),
    maturity = NA_character_,
    timing = rep(cal_years, each = length(cal_lengths)),
    observed = rep(c(0.05, 0.15, 0.35, 0.45), times = length(cal_years)),
    unit = "proportion",
    uncertainty = "~ dmultinom_robust(size = 100, prob = lengthcomp_retained_proportion)"
  ),
  # Directed fishery discarded length comps
  data.frame(
    type = "length_comp",
    fleet = "pot_fleet",
    age = NA_real_,
    length = rep(cal_lengths, times = length(cal_years)),
    maturity = NA_character_,
    timing = rep(cal_years, each = length(cal_lengths)),
    observed = rep(c(0.40, 0.35, 0.15, 0.10), times = length(cal_years)),
    unit = "proportion",
    uncertainty = "~ dmultinom_robust(size = 50, prob = lengthcomp_discarded_proportion)"
  ),
  # Survey mature biomass index
  data.frame(
    type = "index",
    fleet = "survey_fleet",
    age = NA_real_,
    length = NA_real_,
    maturity = "mature",
    timing = cal_years,
    observed = c(50, 55, 52),
    unit = "mt",
    uncertainty = "~ dlnorm(meanlog = log_index_expected, sdlog = 0.1)"
  ),
  # Survey immature length comps
  data.frame(
    type = "length_comp",
    fleet = "survey_fleet",
    age = NA_real_,
    length = rep(cal_lengths, times = length(cal_years)),
    maturity = "immature",
    timing = rep(cal_years, each = length(cal_lengths)),
    observed = rep(c(0.45, 0.30, 0.15, 0.10), times = length(cal_years)),
    unit = "proportion",
    uncertainty = "~ dmultinom_robust(size = 100, prob = lengthcomp_immature_proportion)"
  ),
  # Survey mature length comps
  data.frame(
    type = "length_comp",
    fleet = "survey_fleet",
    age = NA_real_,
    length = rep(cal_lengths, times = length(cal_years)),
    maturity = "mature",
    timing = rep(cal_years, each = length(cal_lengths)),
    observed = rep(c(0.05, 0.20, 0.35, 0.40), times = length(cal_years)),
    unit = "proportion",
    uncertainty = "~ dmultinom_robust(size = 100, prob = lengthcomp_mature_proportion)"
  ),
  # Empirical weight at length
  data.frame(
    type = "weight_at_length",
    fleet = NA_character_,
    age = NA_real_,
    length = rep(cal_lengths, times = 2),
    maturity = rep(c("immature", "mature"), each = length(cal_lengths)),
    timing = NA_real_,
    observed = rep(cal_weights, times = 2),
    unit = "mt",
    uncertainty = NA_character_
  ),
  # Terminal molt probability at length by year (including terminal + 1)
  data.frame(
    type = "terminal_molt_probability_at_length",
    fleet = NA_character_,
    age = NA_real_,
    length = rep(cal_lengths, times = length(cal_years) + 1),
    maturity = "immature",
    timing = rep(c(cal_years, max(cal_years) + 1), each = length(cal_lengths)),
    observed = rep(cal_terminal_molt, times = length(cal_years) + 1),
    unit = "proportion",
    uncertainty = NA_character_
  ),
  # Growth increment observations (fleet = NA)
  data.frame(
    type = "growth_increment",
    fleet = NA_character_,
    age = NA_real_,
    length = c(27.5, 32.5),
    maturity = "immature",
    timing = NA_real_,
    observed = c(8.0, 9.0),
    unit = "mm",
    uncertainty = "~ dlnorm(meanlog = log_growth_increment_expected, sdlog = 0.05)"
  )
)

cal_frame <- FIMSFrame(cal_data)
cal_default_parameters <- setup_default_parameters(
  cal_frame,
  model_type = "CatchAtLength"
)

## IO correctness ----
test_that("`linear_gamma_increment_growth()` produces a valid upper-triangular transition matrix", {
  length_edges <- c(25, 30, 35, 40, 45)
  length_midpoints <- c(27.5, 32.5, 37.5, 42.5)
  growth_out <- FIMS:::linear_gamma_increment_growth(
    length_edges = length_edges,
    length_midpoints = length_midpoints,
    observed_premolt_lengths = c(27.5, 32.5),
    weight_at_length = list(immature = cal_weights, mature = cal_weights),
    growth_intercept = 5.0,
    growth_slope = 0.1,
    growth_scale = 0.75
  )
  transition <- growth_out[["growth_transition"]]

  #' @description Test that the growth transition matrix has 1 row and column per length bin.
  expect_equal(
    object = dim(transition),
    expected = c(4L, 4L)
  )
  #' @description Test that each row of the growth transition matrix sums to 1.
  expect_equal(
    object = rowSums(transition),
    expected = rep(1, 4),
    tolerance = 1e-12
  )
  #' @description Test that entries below the diagonal of the growth transition matrix are 0 (no shrinkage below the premolt bin).
  expect_equal(
    object = transition[lower.tri(transition)],
    expected = rep(0, 6)
  )
  #' @description Test that expected growth increments at observed premolt lengths equal intercept + slope * length.
  expect_equal(
    object = growth_out[["growth_increment_expected"]],
    expected = 5.0 + 0.1 * c(27.5, 32.5),
    tolerance = 1e-12
  )
})

test_that("`gamma_length_recruitment_distribution()` sums to 1 and zeroes bins above max_recruit_length_bin", {
  length_edges <- c(25, 30, 35, 40, 45)
  rec_dist <- FIMS:::gamma_length_recruitment_distribution(
    length_edges = length_edges,
    recruit_gamma_shape = 32.5,
    recruit_gamma_scale = 1.0,
    max_recruit_length_bin = 3L
  )

  #' @description Test that the recruitment length distribution sums to 1.
  expect_equal(
    object = sum(rec_dist),
    expected = 1.0,
    tolerance = 1e-12
  )
  #' @description Test that bins above max_recruit_length_bin receive 0 recruitment proportion.
  expect_equal(
    object = rec_dist[4],
    expected = 0
  )
})

## Edge handling ----
test_that("`catch_at_length()` conserves total numbers when M = F = 0 and recruitment is 0", {
  zero_mortality_parameters <- cal_default_parameters |>
    dplyr::mutate(
      value = dplyr::case_when(
        .data[["module_name"]] == "Population" &
          .data[["label"]] == "log_M" ~ -200,
        .data[["module_name"]] == "Population" &
          .data[["label"]] == "log_M_immature_offset" ~ 0,
        .data[["module_name"]] == "Fleet" &
          .data[["label"]] == "log_Fmort" ~ -200,
        .data[["module_name"]] == "Recruitment" &
          .data[["label"]] == "log_r" ~ -200,
        .default = .data[["value"]]
      )
    )
  report <- zero_mortality_parameters |>
    initialize_fims(data = cal_frame) |>
    fit_fims(optimize = FALSE) |>
    get_report()

  n_immature <- matrix(
    report[["numbers_at_length_immature"]][[1]],
    nrow = length(cal_years) + 1,
    ncol = length(cal_lengths),
    byrow = TRUE
  )
  n_mature <- matrix(
    report[["numbers_at_length_mature"]][[1]],
    nrow = length(cal_years) + 1,
    ncol = length(cal_lengths),
    byrow = TRUE
  )
  total_by_year <- rowSums(n_immature + n_mature)

  #' @description Test that total numbers across immature and mature stages are conserved across years when M = F = 0 and recruitment is 0.
  expect_equal(
    object = total_by_year,
    expected = rep(total_by_year[1], length(cal_years) + 1),
    tolerance = 1e-10
  )
  #' @description Test that mature numbers at every length bin never decrease when M = F = 0 (mature crabs never return to immature).
  expect_true(
    object = all(diff(n_mature) >= -1e-10)
  )
})

test_that("`catch_at_length()` satisfies catch decomposition and spawning biomass identities", {
  fit <- cal_default_parameters |>
    initialize_fims(data = cal_frame) |>
    fit_fims(optimize = FALSE)
  report <- get_report(fit)

  #' @description Test that retained plus discarded catch numbers at length equal total catch numbers at length for the pot fleet.
  expect_equal(
    object = report[["catch_retained_numbers_at_length"]][[1]] +
      report[["catch_discarded_numbers_at_length"]][[1]],
    expected = report[["catch_numbers_at_length"]][[1]],
    tolerance = 1e-12
  )
  #' @description Test that retained plus discarded catch weight at length equal total catch weight at length for the pot fleet.
  expect_equal(
    object = report[["catch_retained_weight_at_length"]][[1]] +
      report[["catch_discarded_weight_at_length"]][[1]],
    expected = report[["catch_weight_at_length"]][[1]],
    tolerance = 1e-12
  )
  #' @description Test that annual retained plus discarded catch weight equal annual total catch weight for the pot fleet.
  expect_equal(
    object = report[["catch_retained_expected"]][[1]] +
      report[["catch_discarded_expected"]][[1]],
    expected = report[["catch_weight"]][[1]],
    tolerance = 1e-12
  )

  # Spawning biomass is mature numbers after season 2 times weight at length.
  n_mature <- matrix(
    report[["numbers_at_length_mature"]][[1]],
    nrow = length(cal_years) + 1,
    ncol = length(cal_lengths),
    byrow = TRUE
  )[seq_along(cal_years), , drop = FALSE]
  m_mature <- matrix(
    report[["mortality_M_mature"]][[1]],
    nrow = length(cal_years),
    ncol = length(cal_lengths),
    byrow = TRUE
  )
  f_total <- matrix(
    report[["mortality_F"]][[1]],
    nrow = length(cal_years),
    ncol = length(cal_lengths),
    byrow = TRUE
  )
  mature_after_season2 <- n_mature * exp(-(0.62 + 0.01) * m_mature - f_total)
  expected_ssb <- as.vector(mature_after_season2 %*% cal_weights)

  #' @description Test that spawning_biomass equals mature numbers after season 2 times weight at length.
  expect_equal(
    object = report[["spawning_biomass"]][[1]],
    expected = expected_ssb,
    tolerance = 1e-12
  )
})

test_that("`LengthSpecific` selectivity and `dmultinom_robust()` match analytical formulas", {
  logit_values <- c(-2, -0.5, 0.5, 2)
  sel_params <- cal_default_parameters |>
    dplyr::filter(
      !(.data[["module_name"]] == "Selectivity" &
        .data[["fleet"]] == "survey_fleet")
    ) |>
    dplyr::bind_rows(
      setup_default_Selectivity(
        cal_frame,
        fleet = "survey_fleet",
        module_type = "LengthSpecific"
      ) |>
        dplyr::mutate(value = logit_values)
    )
  report <- sel_params |>
    initialize_fims(data = cal_frame) |>
    fit_fims(optimize = FALSE) |>
    get_report()
  survey_realized_sel <- report[["index_numbers_at_length"]][[2]][seq_along(cal_lengths)] /
    report[["numbers_at_length_mature"]][[1]][seq_along(cal_lengths)]

  #' @description Test that LengthSpecific selectivity in each year equals plogis(logit_sel_at_length).
  expect_equal(
    object = survey_realized_sel,
    expected = stats::plogis(logit_values),
    tolerance = 1e-12
  )

  # Direct check of robust_normal_multinomial_lpdf() against the GMACS formula.
  obs_counts <- c(10, 20, 30, 40)
  pred_probs <- c(0.15, 0.25, 0.30, 0.30)
  nsamp <- sum(obs_counts)
  offset <- 1e-8
  obs_p <- (obs_counts / nsamp + offset) / sum(obs_counts / nsamp + offset)
  pred_p <- (pred_probs + offset) / sum(pred_probs + offset)
  nbin <- length(obs_counts)
  var_term <- 0.1 / nbin + obs_p * (1 - obs_p)
  scaled_sq <- 0.5 * (pred_p - obs_p)^2 / var_term
  hand_loglik <- sum(
    log(exp(-nsamp * scaled_sq) + 0.01) - 0.5 * log(var_term / nsamp)
  )

  #' @description Test that robust_normal_multinomial_lpdf() matches the GMACS robust normal approximation to the multinomial log-likelihood.
  expect_equal(
    object = sum(FIMS:::robust_normal_multinomial_lpdf(
      matrix(obs_counts, nrow = 1),
      matrix(pred_probs, nrow = 1)
    )),
    expected = hand_loglik,
    tolerance = 1e-12
  )
})

test_that("`add_process()` by length and `add_priors()` with transform work in `CatchAtLength`", {
  logit_values <- c(-1.5, -0.5, 0.5, 1.5)
  rw_sd <- 0.5
  prior_means <- c(0.2, 0.4, 0.6, 0.8)
  prior_sds <- c(0.05, 0.05, 0.05, 0.05)

  custom_params <- cal_default_parameters |>
    dplyr::filter(
      !(.data[["module_name"]] == "Selectivity" &
        .data[["fleet"]] == "survey_fleet")
    ) |>
    dplyr::bind_rows(
      setup_default_Selectivity(
        cal_frame,
        fleet = "survey_fleet",
        module_type = "LengthSpecific"
      ) |>
        dplyr::mutate(value = logit_values)
    ) |>
    add_process(
      logit_sel_at_length ~ rw(1 | length),
      module_name = "Selectivity",
      fleet = "survey_fleet",
      estimation_type = "fixed_effects",
      sd = list(value = rw_sd, estimation_type = "constant")
    ) |>
    add_priors(
      logit_sel_at_length ~ normal(mean = prior_means, sd = prior_sds),
      module_name = "Selectivity",
      fleet = "survey_fleet",
      transform = "inv_logit"
    ) |>
    add_priors(
      log_M ~ normal(mean = 0.25, sd = 0.05),
      module_name = "Population",
      transform = "exp"
    )

  init <- initialize_fims(custom_params, cal_frame)
  fit <- fit_fims(init, optimize = FALSE)
  report <- get_report(fit)
  nll <- stats::setNames(
    report[["nll_components"]],
    FIMS:::label_nll_components(init[["model_data"]])
  )

  #' @description Test that the natural-scale inv_logit prior on logit_sel_at_length equals -sum(dnorm(plogis(x), mean, sd, log = TRUE)).
  expect_equal(
    object = unname(nll[1]),
    expected = -sum(stats::dnorm(
      stats::plogis(logit_values), prior_means, prior_sds,
      log = TRUE
    )),
    tolerance = 1e-12
  )
  #' @description Test that the natural-scale exp prior on log_M equals -dnorm(exp(log_M), mean, sd, log = TRUE).
  expect_equal(
    object = unname(nll[2]),
    expected = -stats::dnorm(0.25, 0.25, 0.05, log = TRUE),
    tolerance = 1e-12
  )
  #' @description Test that the rw(1 | length) process density on logit_sel_at_length equals -sum(dnorm(diff(x), 0, sd, log = TRUE)).
  expect_equal(
    object = unname(nll[4]),
    expected = -sum(stats::dnorm(diff(logit_values), 0, rw_sd, log = TRUE)),
    tolerance = 1e-12
  )

  estimates <- get_estimates(fit)
  #' @description Test that get_estimates() returns numbers_at_length_immature, numbers_at_length_mature, and spawning_biomass rows with length populated.
  expect_true(
    object = all(
      c(
        "numbers_at_length_immature",
        "numbers_at_length_mature",
        "spawning_biomass"
      ) %in% estimates[["label"]]
    ) && !all(is.na(estimates[["length"]]))
  )

  simulated <- simulate_fims(fit, number_of_simulations = 1)
  #' @description Test that simulate_fims() returns a valid simulated data tibble for a catch-at-length model.
  expect_s4_class(
    object = FIMSFrame(simulated[[1]][["data"]]),
    class = "FIMSFrame"
  )
})

## Error handling ----
test_that("`initialize_fims()` refuses observed length compositions in a year with 0 catch", {
  zero_catch_data <- cal_data
  zero_catch_data[["observed"]][
    zero_catch_data[["fleet"]] == "pot_fleet" &
      zero_catch_data[["type"]] %in% c("catch_retained", "catch_discarded") &
      zero_catch_data[["timing"]] == 2002
  ] <- 0
  zero_catch_frame <- FIMSFrame(zero_catch_data)
  zero_catch_params <- setup_default_parameters(
    zero_catch_frame,
    model_type = "CatchAtLength"
  )

  #' @description Test that initialize_fims() aborts when a fishing fleet has observed length_comp data in a year where all catch is 0.
  expect_error(
    object = initialize_fims(zero_catch_params, zero_catch_frame),
    regexp = "has observed.*length_comp.*data in year.*2002.*when catch is 0"
  )
})
